<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
<style>
/* ─── Reset & Base ─── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --color-dark: oklch(15% 0.01 0);
  --color-text: oklch(20% 0.01 0);
  --color-text-secondary: oklch(45% 0.01 0);
  --color-text-tertiary: oklch(60% 0.01 0);
  --color-border: oklch(90% 0.005 0);
  --color-surface: oklch(97% 0.005 0);
  --color-surface-hover: oklch(95% 0.005 0);
  --color-white: oklch(100% 0 0);
  --color-accent: oklch(55% 0.25 285);
  --color-accent-hover: oklch(48% 0.27 285);
  --color-accent-light: oklch(95% 0.05 285);
  --color-accent-subtle: oklch(90% 0.08 285);
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 20px;
  --radius-pill: 100px;
  --shadow-sm: 0 1px 2px oklch(0% 0 0 / 0.05);
  --shadow-md: 0 4px 12px oklch(0% 0 0 / 0.08);
  --shadow-lg: 0 8px 30px oklch(0% 0 0 / 0.1);
  --transition-fast: 200ms cubic-bezier(0.4, 0, 0.2, 1);
  --transition-base: 280ms cubic-bezier(0.4, 0, 0.2, 1);
  --max-width: 1200px;
}

html { scroll-behavior: smooth; -webkit-font-smoothing: antialiased; -moz-osx-font-smoothing: grayscale; }

body {
  font-family: var(--font-sans);
  color: var(--color-text);
  background: var(--color-white);
  line-height: 1.6;
  overflow-x: hidden;
}

a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
img { max-width: 100%; display: block; }

.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

/* ─── Announcement Bar ─── */
.announcement-bar {
  background: var(--color-dark);
  color: var(--color-white);
  text-align: center;
  padding: 10px 24px;
  font-size: 13px;
  font-weight: 500;
  letter-spacing: 0.02em;
}

.announcement-bar span {
  opacity: 0.7;
}

.announcement-bar a {
  color: var(--color-white);
  text-decoration: underline;
  text-underline-offset: 2px;
  margin-left: 4px;
  transition: opacity var(--transition-fast);
}

.announcement-bar a:hover { opacity: 0.8; }

/* ─── Navigation ─── */
.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: oklch(100% 0 0 / 0.9);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--color-border);
}

.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
}

.nav-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 18px;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--color-dark);
}

.nav-logo svg {
  width: 28px;
  height: 28px;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 32px;
}

.nav-link {
  font-size: 14px;
  font-weight: 500;
  color: var(--color-text-secondary);
  transition: color var(--transition-fast);
}

.nav-link:hover { color: var(--color-text); }

.nav-cta {
  display: inline-flex;
  align-items: center;
  padding: 8px 20px;
  background: var(--color-dark);
  color: var(--color-white);
  font-size: 14px;
  font-weight: 600;
  border-radius: var(--radius-pill);
  transition: background var(--transition-fast), transform var(--transition-fast);
}

.nav-cta:hover {
  background: oklch(25% 0.01 0);
  transform: translateY(-1px);
}

.mobile-menu-btn {
  display: none;
  width: 40px;
  height: 40px;
  align-items: center;
  justify-content: center;
}

.mobile-menu-btn svg {
  width: 24px;
  height: 24px;
  stroke: var(--color-text);
}

/* ─── Hero ─── */
.hero {
  padding: 80px 0 60px;
  text-align: center;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 16px 6px 8px;
  background: var(--color-accent-light);
  color: var(--color-accent);
  font-size: 13px;
  font-weight: 600;
  border-radius: var(--radius-pill);
  margin-bottom: 28px;
}

.hero-badge-dot {
  width: 8px;
  height: 8px;
  background: var(--color-accent);
  border-radius: 50%;
  animation: pulse-dot 2s ease-in-out infinite;
}

@keyframes pulse-dot {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.6; transform: scale(0.85); }
}

.hero h1 {
  font-size: clamp(40px, 6vw, 72px);
  font-weight: 800;
  line-height: 1.05;
  letter-spacing: -0.035em;
  color: var(--color-dark);
  max-width: 800px;
  margin: 0 auto 20px;
}

.hero-subtitle {
  font-size: clamp(16px, 2vw, 19px);
  color: var(--color-text-secondary);
  max-width: 540px;
  margin: 0 auto 40px;
  line-height: 1.6;
}

.hero-actions {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  flex-wrap: wrap;
}

.btn-primary {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 14px 32px;
  background: var(--color-accent);
  color: var(--color-white);
  font-size: 16px;
  font-weight: 600;
  border-radius: var(--radius-pill);
  transition: background var(--transition-fast), transform var(--transition-fast), box-shadow var(--transition-fast);
  box-shadow: 0 4px 16px oklch(55% 0.25 285 / 0.3);
}

.btn-primary:hover {
  background: var(--color-accent-hover);
  transform: translateY(-2px);
  box-shadow: 0 6px 24px oklch(55% 0.25 285 / 0.4);
}

.btn-secondary {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 14px 32px;
  background: var(--color-white);
  color: var(--color-text);
  font-size: 16px;
  font-weight: 600;
  border-radius: var(--radius-pill);
  border: 1.5px solid var(--color-border);
  transition: all var(--transition-fast);
}

.btn-secondary:hover {
  border-color: oklch(75% 0.005 0);
  background: var(--color-surface);
  transform: translateY(-2px);
}

/* ─── Trusted By ─── */
.trusted-by {
  padding: 50px 0;
  border-top: 1px solid var(--color-border);
  border-bottom: 1px solid var(--color-border);
  overflow: hidden;
}

.trusted-by-label {
  text-align: center;
  font-size: 13px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--color-text-tertiary);
  margin-bottom: 28px;
}

.marquee-wrapper {
  position: relative;
  overflow: hidden;
  mask-image: linear-gradient(to right, transparent, black 10%, black 90%, transparent);
  -webkit-mask-image: linear-gradient(to right, transparent, black 10%, black 90%, transparent);
}

.marquee-track {
  display: flex;
  align-items: center;
  gap: 56px;
  width: max-content;
  animation: marquee-scroll 30s linear infinite;
}

.marquee-track:hover { animation-play-state: paused; }

@keyframes marquee-scroll {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

.marquee-logo {
  flex-shrink: 0;
  font-size: 17px;
  font-weight: 700;
  color: var(--color-text-tertiary);
  white-space: nowrap;
  opacity: 0.55;
  transition: opacity var(--transition-fast);
  user-select: none;
  letter-spacing: -0.01em;
}

.marquee-track:hover .marquee-logo { opacity: 0.8; }

/* ─── Stats ─── */
.stats {
  padding: 100px 0;
}

.stats-header {
  text-align: center;
  margin-bottom: 56px;
}

.stats-header p {
  font-size: 15px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--color-accent);
  margin-bottom: 12px;
}

.stats-header h2 {
  font-size: clamp(28px, 4vw, 42px);
  font-weight: 800;
  letter-spacing: -0.03em;
  color: var(--color-dark);
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  max-width: 900px;
  margin: 0 auto;
}

.stat-card {
  text-align: center;
  padding: 40px 24px;
  background: var(--color-surface);
  border-radius: var(--radius-xl);
  border: 1px solid var(--color-border);
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}

.stat-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.stat-number {
  font-size: clamp(36px, 5vw, 56px);
  font-weight: 800;
  letter-spacing: -0.03em;
  color: var(--color-dark);
  line-height: 1;
  margin-bottom: 8px;
}

.stat-label {
  font-size: 15px;
  font-weight: 500;
  color: var(--color-text-secondary);
  text-transform: capitalize;
}

/* ─── Features: Search ─── */
.features-search {
  padding: 100px 0;
  background: var(--color-surface);
}

.section-label {
  font-size: 14px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--color-accent);
  margin-bottom: 12px;
}

.section-title {
  font-size: clamp(28px, 4vw, 42px);
  font-weight: 800;
  letter-spacing: -0.03em;
  color: var(--color-dark);
  margin-bottom: 12px;
}

.section-subtitle {
  font-size: 17px;
  color: var(--color-text-secondary);
  max-width: 560px;
  line-height: 1.6;
  margin-bottom: 40px;
}

.search-tabs {
  display: flex;
  gap: 4px;
  background: var(--color-white);
  padding: 4px;
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border);
  margin-bottom: 24px;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}

.search-tabs::-webkit-scrollbar { display: none; }

.search-tab {
  flex-shrink: 0;
  padding: 10px 20px;
  font-size: 14px;
  font-weight: 500;
  color: var(--color-text-secondary);
  border-radius: var(--radius-sm);
  transition: all var(--transition-fast);
  white-space: nowrap;
}

.search-tab:hover {
  color: var(--color-text);
  background: var(--color-surface);
}

.search-tab.active {
  background: var(--color-dark);
  color: var(--color-white);
  font-weight: 600;
}

.filter-pills {
  display: flex;
  gap: 8px;
  margin-bottom: 32px;
  overflow-x: auto;
  padding-bottom: 4px;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}

.filter-pills::-webkit-scrollbar { display: none; }

.filter-pill {
  flex-shrink: 0;
  padding: 8px 18px;
  font-size: 13px;
  font-weight: 500;
  color: var(--color-text-secondary);
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-pill);
  transition: all var(--transition-fast);
  white-space: nowrap;
}

.filter-pill:hover {
  border-color: oklch(70% 0.01 0);
  color: var(--color-text);
}

.filter-pill.active {
  background: var(--color-accent);
  color: var(--color-white);
  border-color: var(--color-accent);
}

.screenshot-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}

.screenshot-card {
  aspect-ratio: 9 / 16;
  background: var(--color-white);
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border);
  overflow: hidden;
  transition: transform var(--transition-base), box-shadow var(--transition-base);
  position: relative;
}

.screenshot-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.screenshot-placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 20px;
}

.screenshot-placeholder .phone-frame {
  width: 60%;
  height: 65%;
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  display: flex;
  flex-direction: column;
  padding: 12%;
  gap: 8%;
}

.phone-frame .ph-bar {
  height: 8%;
  background: oklch(88% 0.01 0);
  border-radius: 4px;
}

.phone-frame .ph-bar.short { width: 60%; }
.phone-frame .ph-bar.medium { width: 80%; }

.phone-frame .ph-block {
  flex: 1;
  background: oklch(92% 0.01 0);
  border-radius: 6px;
}

.screenshot-card-label {
  position: absolute;
  bottom: 12px;
  left: 12px;
  right: 12px;
  padding: 8px 12px;
  background: oklch(100% 0 0 / 0.9);
  backdrop-filter: blur(8px);
  border-radius: var(--radius-sm);
  font-size: 12px;
  font-weight: 600;
  color: var(--color-text);
  text-align: center;
}

/* ─── Features: Flows ─── */
.features-flows {
  padding: 100px 0;
}

.features-flows .container {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.flows-content { max-width: 480px; }

.flows-toggle {
  display: inline-flex;
  gap: 4px;
  background: var(--color-surface);
  padding: 4px;
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border);
  margin-bottom: 28px;
}

.flows-toggle-btn {
  padding: 10px 22px;
  font-size: 14px;
  font-weight: 500;
  color: var(--color-text-secondary);
  border-radius: var(--radius-sm);
  transition: all var(--transition-fast);
}

.flows-toggle-btn:hover {
  color: var(--color-text);
}

.flows-toggle-btn.active {
  background: var(--color-white);
  color: var(--color-text);
  font-weight: 600;
  box-shadow: var(--shadow-sm);
}

.flows-description {
  font-size: 16px;
  color: var(--color-text-secondary);
  line-height: 1.7;
  transition: opacity var(--transition-base);
}

.flows-visual {
  background: var(--color-surface);
  border-radius: var(--radius-xl);
  border: 1px solid var(--color-border);
  padding: 32px;
  min-height: 400px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.flows-visual-inner {
  display: flex;
  gap: 16px;
  align-items: center;
  width: 100%;
}

.flow-step {
  flex: 1;
  aspect-ratio: 9 / 16;
  max-height: 280px;
  background: var(--color-white);
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border);
  display: flex;
  flex-direction: column;
  padding: 16px;
  gap: 8px;
  transition: transform var(--transition-base);
}

.flow-step:hover { transform: scale(1.03); }

.flow-step .step-dot {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--color-accent-light);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 700;
  color: var(--color-accent);
}

.flow-step .step-lines {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding-top: 8px;
}

.flow-step .step-line {
  height: 6px;
  background: var(--color-surface);
  border-radius: 3px;
}

.flow-step .step-line:nth-child(1) { width: 80%; }
.flow-step .step-line:nth-child(2) { width: 100%; }
.flow-step .step-line:nth-child(3) { width: 60%; }

.flow-arrow {
  flex-shrink: 0;
  width: 20px;
  color: var(--color-text-tertiary);
}

/* ─── Features: Tools ─── */
.features-tools {
  padding: 100px 0;
  background: var(--color-surface);
}

.features-tools .section-header {
  text-align: center;
  margin-bottom: 56px;
}

.features-tools .section-subtitle {
  margin-left: auto;
  margin-right: auto;
  text-align: center;
}

.tools-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.tool-card {
  background: var(--color-white);
  border-radius: var(--radius-xl);
  border: 1px solid var(--color-border);
  padding: 32px;
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}

.tool-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.tool-icon {
  width: 52px;
  height: 52px;
  background: var(--color-accent-light);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
}

.tool-icon svg {
  width: 26px;
  height: 26px;
  color: var(--color-accent);
}

.tool-card h3 {
  font-size: 18px;
  font-weight: 700;
  color: var(--color-dark);
  margin-bottom: 10px;
  letter-spacing: -0.01em;
}

.tool-card p {
  font-size: 14px;
  color: var(--color-text-secondary);
  line-height: 1.65;
}

/* ─── Testimonials ─── */
.testimonials {
  padding: 100px 0;
  overflow: hidden;
}

.testimonials .section-header {
  text-align: center;
  margin-bottom: 56px;
}

.testimonials .section-subtitle {
  margin-left: auto;
  margin-right: auto;
  text-align: center;
}

.testimonials-marquee {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.testimonial-row {
  display: flex;
  gap: 20px;
  width: max-content;
}

.testimonial-row:nth-child(1) { animation: testimonial-scroll-left 40s linear infinite; }
.testimonial-row:nth-child(2) { animation: testimonial-scroll-right 45s linear infinite; }

@keyframes testimonial-scroll-left {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

@keyframes testimonial-scroll-right {
  0% { transform: translateX(-50%); }
  100% { transform: translateX(0); }
}

.testimonial-card {
  flex-shrink: 0;
  width: 400px;
  padding: 28px;
  background: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-xl);
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}

.testimonial-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.testimonial-text {
  font-size: 14px;
  color: var(--color-text-secondary);
  line-height: 1.7;
  margin-bottom: 20px;
}

.testimonial-author {
  display: flex;
  align-items: center;
  gap: 12px;
}

.testimonial-avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--color-accent-light);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 15px;
  font-weight: 700;
  color: var(--color-accent);
  flex-shrink: 0;
}

.testimonial-name {
  font-size: 14px;
  font-weight: 600;
  color: var(--color-dark);
}

.testimonial-role {
  font-size: 12px;
  color: var(--color-text-tertiary);
}

/* ─── CTA Section ─── */
.cta-section {
  padding: 100px 0 60px;
  background: var(--color-dark);
  color: var(--color-white);
  text-align: center;
  overflow: hidden;
}

.cta-section h2 {
  font-size: clamp(28px, 4vw, 46px);
  font-weight: 800;
  letter-spacing: -0.03em;
  margin-bottom: 16px;
}

.cta-section .cta-subtitle {
  font-size: 17px;
  color: oklch(75% 0.01 0);
  max-width: 520px;
  margin: 0 auto 40px;
  line-height: 1.6;
}

.cta-actions {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  flex-wrap: wrap;
  margin-bottom: 80px;
}

.cta-actions .btn-primary {
  background: var(--color-white);
  color: var(--color-dark);
  box-shadow: 0 4px 16px oklch(0% 0 0 / 0.3);
}

.cta-actions .btn-primary:hover {
  background: oklch(95% 0 0);
  box-shadow: 0 6px 24px oklch(0% 0 0 / 0.4);
}

.cta-actions .btn-secondary {
  border-color: oklch(40% 0.01 0);
  color: oklch(80% 0.01 0);
  background: transparent;
}

.cta-actions .btn-secondary:hover {
  border-color: oklch(55% 0.01 0);
  color: var(--color-white);
  background: oklch(25% 0.01 0);
}

.brand-marquee {
  padding-top: 20px;
}

.brand-marquee-row {
  display: flex;
  gap: 24px;
  width: max-content;
  margin-bottom: 16px;
